<script setup>
import {ref,computed} from 'vue';import {store,hoy} from '../store';const mes=ref(new Date());const titulo=computed(()=>mes.value.toLocaleDateString('es-PE',{month:'long',year:'numeric'}));const dias=computed(()=>{const y=mes.value.getFullYear(),m=mes.value.getMonth(),inicio=(new Date(y,m,1).getDay()+6)%7,n=new Date(y,m+1,0).getDate();return [...Array(inicio).fill(null),...Array.from({length:n},(_,i)=>({numero:i+1,fecha:hoy(new Date(y,m,i+1))}))]});function cambiar(n){mes.value=new Date(mes.value.getFullYear(),mes.value.getMonth()+n,1)}
</script><template><h2 class="mb-3">Calendario</h2><div class="card p-3"><div class="d-flex justify-content-between align-items-center mb-3"><button class="btn btn-outline-secondary" @click="cambiar(-1)">Anterior</button><h5 class="text-capitalize">{{titulo}}</h5><button class="btn btn-outline-secondary" @click="cambiar(1)">Siguiente</button></div><div class="calendar"><div v-for="d in ['Lun','Mar','Mié','Jue','Vie','Sáb','Dom']" class="text-center text-secondary small">{{d}}</div><div v-for="(d,i) in dias" :key="i" class="day" :class="{'border-primary':d?.fecha===hoy()}"><template v-if="d"><strong>{{d.numero}}</strong><div v-for="t in store.tareas.filter(t=>t.fecha===d.fecha)" :key="t.id" class="event">{{t.nombre}}</div></template></div></div></div></template>